// tuft geometry: 3 tapered blades fanned around the origin
const bladeW = 0.055, bladeH = 1.0;
const verts = [], uvs = [], idx = [];
const levels = [0, 0.4, 0.75];
for (let b = 0; b < 3; b++) {
  const rot = (b / 3) * Math.PI * 2 + 0.35;
  const ca = Math.cos(rot), sa = Math.sin(rot);
  const lean = 0.14 + b * 0.05; // each blade leans outward a bit
  const baseIdx = verts.length / 3;
  levels.forEach((h) => {
    const w = bladeW * (1 - h * 0.8);
    const ox = sa * lean * h, oz = ca * lean * h;
    verts.push(-w * ca + ox, h * bladeH, w * sa + oz, w * ca + ox, h * bladeH, -w * sa + oz);
    uvs.push(0, h, 1, h);
  });
  verts.push(sa * lean, bladeH, ca * lean); uvs.push(0.5, 1);
  for (let i = 0; i < 2; i++) {
    const k = baseIdx + i * 2;
    idx.push(k, k + 1, k + 2, k + 1, k + 3, k + 2);
  }
  idx.push(baseIdx + 4, baseIdx + 5, baseIdx + 6);
}
